INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('hope-01', 'Your current chapter is not your final story. Hope is still reasonable, even on a slow morning like this.', 'Good morning.', 'hope', '["low","struggling","okay"]'::jsonb, '["life-changes","purpose","failure"]'::jsonb, '["gentle","reflective","friendly"]'::jsonb, FALSE, NULL, 'Write down one thing you still believe is possible.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('hope-02', 'You have survived every hard day so far. That track record matters. Today can still hold something good.', 'Take a breath.', 'hope', '["low","struggling"]'::jsonb, '["life-changes","growth","purpose"]'::jsonb, '["gentle","motivational"]'::jsonb, FALSE, NULL, 'Name one small light in today and sit with it for a minute.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('hope-03', 'Small beginnings count. Plant one hopeful step today and let tomorrow build on it.', 'Good morning.', 'hope', '["okay","good","low"]'::jsonb, '["purpose","growth","relationships"]'::jsonb, '["practical","friendly","motivational"]'::jsonb, FALSE, NULL, 'Send a hopeful message to someone you trust.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('hope-04', 'Feeling low does not mean you are failing. It means you are human and still in the fight.', 'Listen.', 'hope', '["low","struggling"]'::jsonb, '["confidence","purpose","failure"]'::jsonb, '["gentle","reflective"]'::jsonb, FALSE, NULL, 'Write down one thing you still believe is possible.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('hope-05', 'Progress is often invisible before it is obvious. Stay with the process one more day.', 'Keep looking up.', 'hope', '["okay","low","good"]'::jsonb, '["career","business","growth"]'::jsonb, '["motivational","practical"]'::jsonb, FALSE, NULL, 'Name one small light in today and sit with it for a minute.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('hope-06', 'You are allowed to start again today. Yesterday''s weight does not get the final vote.', 'Bold truth:', 'hope', '["struggling","low","okay"]'::jsonb, '["failure","life-changes","purpose"]'::jsonb, '["bold","direct","motivational"]'::jsonb, FALSE, NULL, 'Send a hopeful message to someone you trust.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('conf-01', 'You do not need permission to believe in yourself. Your skills are real and they travel with you.', 'Good morning.', 'confidence', '["low","okay","struggling"]'::jsonb, '["confidence","career","school"]'::jsonb, '["bold","motivational","direct"]'::jsonb, FALSE, NULL, 'Write down three things you are good at.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('conf-02', 'Confidence grows by evidence, not hype. Look at one thing you handled well this week.', 'Gentle reminder.', 'confidence', '["okay","low","good"]'::jsonb, '["confidence","purpose","growth"]'::jsonb, '["gentle","reflective","friendly"]'::jsonb, FALSE, NULL, 'Stand tall, breathe deeply, and say one true strength out loud.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('conf-03', 'You were invited, chosen, or earned your place. Walk in like the room needs what you carry.', 'Before you walk in.', 'confidence', '["okay","good","low"]'::jsonb, '["career","school","business"]'::jsonb, '["bold","motivational","direct"]'::jsonb, FALSE, NULL, 'Do one small thing you have been avoiding to prove you can.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('conf-04', 'Nervous does not mean unready. It means you care. Let care sharpen you, not stop you.', 'Quiet truth.', 'confidence', '["low","struggling","okay"]'::jsonb, '["confidence","school","career"]'::jsonb, '["gentle","reflective"]'::jsonb, FALSE, NULL, 'Write down three things you are good at.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('conf-05', 'Pick one skill you want to trust more, then practice it for ten focused minutes today.', 'Practical step.', 'confidence', '["okay","good"]'::jsonb, '["growth","career","confidence"]'::jsonb, '["practical","direct","motivational"]'::jsonb, FALSE, NULL, 'Do one small thing you have been avoiding to prove you can.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('conf-06', 'People already trust you more than you trust yourself. Borrow their view until yours catches up.', 'Hey, friend.', 'confidence', '["low","okay","good"]'::jsonb, '["relationships","confidence","purpose"]'::jsonb, '["friendly","gentle","motivational"]'::jsonb, FALSE, NULL, 'Stand tall, breathe deeply, and say one true strength out loud.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('mot-01', 'You do not need to feel like it to start. Start small and let motion create motivation.', 'Let''s move.', 'motivation', '["okay","low","good"]'::jsonb, '["growth","career","school"]'::jsonb, '["bold","practical","motivational"]'::jsonb, FALSE, NULL, 'Spend 15 minutes on the task you keep postponing.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('mot-02', 'You are still moving forward even if today feels slow. One focused block can change the day.', 'Midday reset.', 'motivation', '["okay","low","good"]'::jsonb, '["business","career","school"]'::jsonb, '["practical","friendly","motivational"]'::jsonb, FALSE, NULL, 'Break today''s goal into one 10-minute step and start it.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('mot-03', 'Big goals are built from boring reps. Do today''s rep well and trust the compound effect.', 'Gentle push.', 'motivation', '["good","okay","great"]'::jsonb, '["growth","growth","purpose"]'::jsonb, '["practical","reflective"]'::jsonb, FALSE, NULL, 'Spend 15 minutes on the task you keep postponing.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('mot-04', 'Tired is information, not identity. Rest briefly, then take one clear next step.', 'When tired.', 'motivation', '["low","struggling","okay"]'::jsonb, '["growth","life-changes","confidence"]'::jsonb, '["gentle","practical"]'::jsonb, FALSE, NULL, 'Clear one small space to clear your mind.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('mot-05', 'Waiting for perfect conditions wastes good days. Use what you have, where you are, today.', 'Direct word:', 'motivation', '["okay","good","low"]'::jsonb, '["business","career","purpose"]'::jsonb, '["bold","direct"]'::jsonb, FALSE, NULL, 'Break today''s goal into one 10-minute step and start it.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('mot-06', 'You showed up when quitting would have been easier. That counts more than you think.', 'Evening check.', 'motivation', '["good","great","okay"]'::jsonb, '["growth","purpose"]'::jsonb, '["friendly","reflective","motivational"]'::jsonb, FALSE, NULL, 'Clear one small space to clear your mind.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('str-01', 'You can do hard things and still need rest. Strength includes asking for support.', 'When heavy.', 'strength', '["low","struggling"]'::jsonb, '["life-changes","family","failure"]'::jsonb, '["gentle","reflective"]'::jsonb, FALSE, NULL, 'Ask one person for help instead of carrying it alone.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('str-02', 'One breath, one step, one hour at a time. You do not have to carry the whole week today.', 'Take heart.', 'strength', '["struggling","low","okay"]'::jsonb, '["life-changes","finances","purpose"]'::jsonb, '["gentle","practical","friendly"]'::jsonb, FALSE, NULL, 'Take five slow breaths before your next decision.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('str-03', 'You have handled 100% of your hardest days so far. Bring that same steadiness today.', 'Bold reminder.', 'strength', '["low","okay","struggling"]'::jsonb, '["career","failure","life-changes"]'::jsonb, '["bold","motivational"]'::jsonb, FALSE, NULL, 'Take five slow breaths before your next decision.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('str-04', 'Recovery is productive. A rested mind solves what an exhausted one cannot.', 'Permission slip:', 'strength', '["low","struggling","okay"]'::jsonb, '["growth","life-changes","family"]'::jsonb, '["gentle","friendly"]'::jsonb, FALSE, NULL, 'Rest for 20 minutes without guilt â€” strength needs fuel.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('str-05', 'Shrink the problem to the next useful action. Strength loves clarity.', 'Practical aid.', 'strength', '["okay","low"]'::jsonb, '["business","finances","career"]'::jsonb, '["practical","direct"]'::jsonb, FALSE, NULL, 'Ask one person for help instead of carrying it alone.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('str-06', 'You made it through today. That is strength, even if the to-do list is not finished.', 'Evening word.', 'strength', '["low","okay","good"]'::jsonb, '["life-changes","purpose"]'::jsonb, '["reflective","gentle"]'::jsonb, FALSE, NULL, 'Rest for 20 minutes without guilt â€” strength needs fuel.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('cour-01', 'Courage is not the absence of fear. It is one small act done while afraid.', 'Be brave.', 'courage', '["low","okay","struggling"]'::jsonb, '["purpose","career","growth"]'::jsonb, '["bold","motivational"]'::jsonb, FALSE, NULL, 'Take the first small step you have been rehearsing in your head.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('cour-02', 'You do not need to leap. A quiet, steady step forward still counts as brave.', 'Gentle courage.', 'courage', '["okay","low","good"]'::jsonb, '["relationships","career","confidence"]'::jsonb, '["gentle","friendly"]'::jsonb, FALSE, NULL, 'Send the message you are afraid to send.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('cour-03', 'Clarity follows action. Make the small brave choice and adjust as you learn.', 'Decision time.', 'courage', '["okay","good","low"]'::jsonb, '["business","purpose","life-changes"]'::jsonb, '["direct","practical","bold"]'::jsonb, FALSE, NULL, 'Take the first small step you have been rehearsing in your head.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('cour-04', 'Saying no to what drains you is saying yes to what matters. That is courage too.', 'Boundary word.', 'courage', '["okay","low","good"]'::jsonb, '["relationships","family","growth"]'::jsonb, '["direct","gentle","practical"]'::jsonb, FALSE, NULL, 'Say no to one thing that drains you today.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('cour-05', 'You do not need perfection to begin. Give yourself permission to start messy.', 'Before you start.', 'courage', '["struggling","low","okay"]'::jsonb, '["business","school","growth"]'::jsonb, '["motivational","friendly"]'::jsonb, FALSE, NULL, 'Take the first small step you have been rehearsing in your head.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('cour-06', 'Remember a time you were afraid and did it anyway. That same courage is still in you.', 'Reflect.', 'courage', '["low","okay","good"]'::jsonb, '["confidence","purpose","failure"]'::jsonb, '["reflective","gentle"]'::jsonb, FALSE, NULL, 'Say no to one thing that drains you today.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('succ-01', 'Pause and own this win. You worked for it, learned for it, and showed up for it.', 'Celebrate.', 'success', '["great","good","okay"]'::jsonb, '["career","business","growth"]'::jsonb, '["friendly","motivational","reflective"]'::jsonb, FALSE, NULL, 'Write down one win from this week, however small.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('succ-02', 'Success tastes better with gratitude. Notice who helped and what habit carried you.', 'Well earned.', 'success', '["great","good"]'::jsonb, '["relationships","career","purpose"]'::jsonb, '["reflective","friendly"]'::jsonb, FALSE, NULL, 'Thank someone who helped you get this far.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('succ-03', 'Momentum loves direction. Enjoy today, then set one clear next target for tomorrow.', 'Next level.', 'success', '["great","good","okay"]'::jsonb, '["business","growth","career"]'::jsonb, '["bold","practical","motivational"]'::jsonb, FALSE, NULL, 'Set the next small target while momentum is warm.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('succ-04', 'Not every victory is loud. Showing up consistently is a success worth honoring.', 'Quiet win.', 'success', '["good","okay","great"]'::jsonb, '["growth","purpose","confidence"]'::jsonb, '["gentle","reflective"]'::jsonb, FALSE, NULL, 'Write down one win from this week, however small.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('succ-05', 'Your progress can encourage someone behind you. Tell the story honestly, including the hard parts.', 'Share it.', 'success', '["great","good"]'::jsonb, '["relationships","career","purpose"]'::jsonb, '["friendly","motivational"]'::jsonb, FALSE, NULL, 'Thank someone who helped you get this far.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('succ-06', 'One win is a foundation, not a finish line. Keep the habits that built it.', 'Stay grounded.', 'success', '["good","great","okay"]'::jsonb, '["growth","career","growth"]'::jsonb, '["direct","practical"]'::jsonb, FALSE, NULL, 'Set the next small target while momentum is warm.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('fail-01', 'A rejection can close one door without defining your ability. Learn what you can and keep going.', 'After a fall.', 'failure', '["low","struggling","okay"]'::jsonb, '["failure","career","business"]'::jsonb, '["gentle","reflective","friendly"]'::jsonb, FALSE, NULL, 'Write what this setback taught you in one sentence.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('fail-02', 'Failure is feedback with a sting. Adjust one variable and test again â€” that is how breakthroughs form.', 'Try again.', 'failure', '["low","okay","struggling"]'::jsonb, '["business","school","failure"]'::jsonb, '["practical","bold","motivational"]'::jsonb, FALSE, NULL, 'Try the same thing once more with one adjustment.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('fail-03', 'Trying and missing beats watching from the sidelines. Your courage to attempt still counts.', 'No shame here.', 'failure', '["struggling","low"]'::jsonb, '["failure","confidence","purpose"]'::jsonb, '["gentle","friendly"]'::jsonb, FALSE, NULL, 'Share your story with someone safe â€” shame fades in light.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('fail-04', 'This moment feels final but it is not. Many comebacks started exactly where you are now.', 'Direct truth:', 'failure', '["struggling","low","okay"]'::jsonb, '["failure","life-changes","career"]'::jsonb, '["bold","direct","motivational"]'::jsonb, FALSE, NULL, 'Write what this setback taught you in one sentence.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('fail-05', 'One grade does not measure your mind. Review, adjust your method, and keep building understanding.', 'Exam season.', 'failure', '["low","okay","struggling"]'::jsonb, '["school","failure","growth"]'::jsonb, '["practical","friendly"]'::jsonb, FALSE, NULL, 'Try the same thing once more with one adjustment.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('fail-06', 'Slow sales are a season, not a sentence. Talk to one customer today and learn one real need.', 'Business dip.', 'failure', '["low","struggling","okay"]'::jsonb, '["business","failure","finances"]'::jsonb, '["practical","direct"]'::jsonb, FALSE, NULL, 'Try the same thing once more with one adjustment.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('rel-01', 'Healthy bonds are built in small, consistent kindnesses. One warm message can reopen a door.', 'For the heart.', 'relationships', '["okay","low","good"]'::jsonb, '["relationships","family","purpose"]'::jsonb, '["friendly","gentle"]'::jsonb, FALSE, NULL, 'Send someone you appreciate a short message.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('rel-02', 'You do not have to fix them. Sometimes the greatest gift is five minutes of full attention.', 'Listen well.', 'relationships', '["good","okay","great"]'::jsonb, '["relationships","family","career"]'::jsonb, '["practical","friendly","reflective"]'::jsonb, FALSE, NULL, 'Listen fully for five minutes without fixing.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('rel-03', 'A quick, sincere apology heals faster than a perfect one delayed. Keep it simple and kind.', 'Repair note.', 'relationships', '["low","okay","struggling"]'::jsonb, '["relationships","family"]'::jsonb, '["direct","gentle","practical"]'::jsonb, FALSE, NULL, 'Apologize for one small thing quickly and kindly.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('rel-04', 'Loneliness lies about your worth. You are still lovable and still needed, even tonight.', 'Feeling lonely?', 'relationships', '["low","struggling"]'::jsonb, '["relationships","life-changes","purpose"]'::jsonb, '["gentle","friendly","reflective"]'::jsonb, FALSE, NULL, 'Send someone you appreciate a short message.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('rel-05', 'Grand gestures fade; daily thoughtfulness lasts. Do one tiny loving thing on purpose today.', 'Love in action.', 'relationships', '["good","great","okay"]'::jsonb, '["relationships","family"]'::jsonb, '["friendly","practical"]'::jsonb, FALSE, NULL, 'Send someone you appreciate a short message.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('rel-06', 'You can be honest and gentle at once. Say the true thing with care and listen to the reply.', 'Hard talk.', 'relationships', '["okay","low","good"]'::jsonb, '["relationships","family","career"]'::jsonb, '["direct","reflective"]'::jsonb, FALSE, NULL, 'Listen fully for five minutes without fixing.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('car-01', 'Each application is a seed. You only need one yes. Improve one line and plant another today.', 'Job hunt day.', 'career', '["low","okay","struggling"]'::jsonb, '["career","failure","purpose"]'::jsonb, '["practical","motivational","friendly"]'::jsonb, FALSE, NULL, 'Apply for one opportunity before the day ends.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('car-02', 'They already saw something in you on paper. Now let them meet the person behind it â€” calm and curious.', 'Interview nerves.', 'career', '["okay","low","good"]'::jsonb, '["career","confidence"]'::jsonb, '["friendly","bold","practical"]'::jsonb, FALSE, NULL, 'Message one contact to ask for advice, not a job.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('car-03', 'Nothing you learned is wasted. Your past skills are raw material for your next role.', 'Career pivot.', 'career', '["okay","low","good"]'::jsonb, '["career","life-changes","purpose"]'::jsonb, '["reflective","practical"]'::jsonb, FALSE, NULL, 'Improve one line of your CV today.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('car-04', 'You cannot do everything today, but you can do the most important thing well. Start there.', 'Work pressure.', 'career', '["struggling","low","okay"]'::jsonb, '["career","business"]'::jsonb, '["direct","practical"]'::jsonb, FALSE, NULL, 'Apply for one opportunity before the day ends.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('car-05', 'Even a hard job teaches discipline, patience, and skill. Extract the lesson while you plan ahead.', 'Stuck at work?', 'career', '["okay","low"]'::jsonb, '["career","growth"]'::jsonb, '["reflective","motivational"]'::jsonb, FALSE, NULL, 'Improve one line of your CV today.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('car-06', 'Opportunities travel through people. One honest conversation can open what applications cannot.', 'Bold move.', 'career', '["good","okay","great"]'::jsonb, '["career","business","relationships"]'::jsonb, '["bold","friendly"]'::jsonb, FALSE, NULL, 'Message one contact to ask for advice, not a job.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('mon-01', 'Money pressure is real, but panic spends energy you need for solutions. Calm first, plan next.', 'Money stress.', 'money', '["low","struggling","okay"]'::jsonb, '["finances","life-changes"]'::jsonb, '["gentle","practical"]'::jsonb, FALSE, NULL, 'Write down every spend from yesterday without judgment.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('mon-02', 'Wealth is built in tiny consistent moves. Even a dollar saved proves you are in control.', 'Small saver.', 'money', '["okay","low","good"]'::jsonb, '["finances","growth","growth"]'::jsonb, '["practical","friendly","motivational"]'::jsonb, FALSE, NULL, 'Move a tiny amount to savings, even $1.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('mon-03', 'Revenue is vanity, cash flow is sanity. Review one number today and act on what it tells you.', 'Business cash.', 'money', '["okay","low","struggling"]'::jsonb, '["business","finances"]'::jsonb, '["direct","practical"]'::jsonb, FALSE, NULL, 'Write down every spend from yesterday without judgment.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('mon-04', 'Scarcity shouts, but inventory whispers truth. List what you already have before chasing more.', 'Gratitude check.', 'money', '["low","okay","good"]'::jsonb, '["finances","growth"]'::jsonb, '["reflective","gentle"]'::jsonb, FALSE, NULL, 'List three things you already have that save you money.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('mon-05', 'Debt feels endless until you attack one piece. Choose the smallest balance and make a plan.', 'Debt weight.', 'money', '["struggling","low"]'::jsonb, '["finances","life-changes"]'::jsonb, '["direct","gentle","practical"]'::jsonb, FALSE, NULL, 'Write down every spend from yesterday without judgment.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('mon-06', 'Money follows value. Solve one painful problem for someone and the income will follow effort.', 'Bold earner.', 'money', '["good","okay","great"]'::jsonb, '["business","finances","purpose"]'::jsonb, '["bold","motivational"]'::jsonb, FALSE, NULL, 'Move a tiny amount to savings, even $1.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('pur-01', 'Your life is not random. Someone needs the exact lessons only your journey taught you.', 'Why you?', 'purpose', '["low","okay","struggling"]'::jsonb, '["purpose","life-changes","growth"]'::jsonb, '["reflective","gentle","friendly"]'::jsonb, FALSE, NULL, 'Write one sentence about who you want to help.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('pur-02', 'Pay attention to what energizes you. Purpose often hides inside quiet curiosity.', 'Direction hint.', 'purpose', '["okay","good","low"]'::jsonb, '["purpose","career","growth"]'::jsonb, '["reflective","practical"]'::jsonb, FALSE, NULL, 'Spend 10 minutes on work that feels meaningful.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('pur-03', 'If fear were silent, what would you attempt? Write it down â€” that is a clue to purpose.', 'Fear check.', 'purpose', '["okay","low","good"]'::jsonb, '["purpose","confidence","life-changes"]'::jsonb, '["bold","reflective","direct"]'::jsonb, FALSE, NULL, 'Ask: what would I do if I were not afraid? Write it down.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('pur-04', 'You do not need a stage to live on purpose. Help one person near you today with excellence.', 'Serve small.', 'purpose', '["good","okay","great"]'::jsonb, '["purpose","relationships","career"]'::jsonb, '["practical","friendly"]'::jsonb, FALSE, NULL, 'Write one sentence about who you want to help.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('pur-05', 'Delay is not denial. Use this quiet season to build skill for the louder one coming.', 'Waiting season.', 'purpose', '["low","struggling","okay"]'::jsonb, '["purpose","failure","life-changes"]'::jsonb, '["gentle","reflective"]'::jsonb, FALSE, NULL, 'Spend 10 minutes on work that feels meaningful.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('pur-06', 'Playing small does not serve anyone. Own the bigger vision quietly forming in you.', 'Bold calling.', 'purpose', '["good","great","okay"]'::jsonb, '["purpose","career","growth"]'::jsonb, '["bold","motivational"]'::jsonb, FALSE, NULL, 'Ask: what would I do if I were not afraid? Write it down.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('sb-01', 'Doubt is loud but not accurate. Counter one lie with one documented fact about you.', 'Truth check.', 'self-belief', '["low","struggling","okay"]'::jsonb, '["confidence","failure","purpose"]'::jsonb, '["direct","gentle","reflective"]'::jsonb, FALSE, NULL, 'Repeat one true fact about your ability out loud.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('sb-02', 'You have proof of capability in your past. Revisit one win and borrow its confidence today.', 'Evidence file.', 'self-belief', '["low","okay","good"]'::jsonb, '["confidence","growth","career"]'::jsonb, '["reflective","practical"]'::jsonb, FALSE, NULL, 'Revisit a past win and write how you earned it.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('sb-03', 'You would not speak to a friend the way you speak to yourself. Offer yourself the same grace.', 'Inner critic.', 'self-belief', '["struggling","low"]'::jsonb, '["confidence","relationships","purpose"]'::jsonb, '["gentle","friendly"]'::jsonb, FALSE, NULL, 'Stop one self-critical sentence and replace it with truth.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('sb-04', 'Stop shrinking to stay comfortable. Take up the full space your talent deserves today.', 'Bold self.', 'self-belief', '["good","okay","great"]'::jsonb, '["confidence","career","career"]'::jsonb, '["bold","motivational","direct"]'::jsonb, FALSE, NULL, 'Repeat one true fact about your ability out loud.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('sb-05', 'Struggling to grasp something means your brain is growing, not failing. Keep practicing deliberately.', 'School mind.', 'self-belief', '["low","okay","struggling"]'::jsonb, '["school","confidence","growth"]'::jsonb, '["friendly","practical"]'::jsonb, FALSE, NULL, 'Revisit a past win and write how you earned it.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('sb-06', 'Your past mistakes do not own your future choices. Write one truer sentence about who you are.', 'Fresh page.', 'self-belief', '["low","struggling","okay"]'::jsonb, '["life-changes","failure","purpose"]'::jsonb, '["reflective","gentle"]'::jsonb, FALSE, NULL, 'Stop one self-critical sentence and replace it with truth.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('grat-01', 'Gratitude turns ordinary mornings into gifts. Name three small goods before you rush out.', 'Thankful morning.', 'gratitude', '["good","great","okay"]'::jsonb, '["growth","relationships","purpose"]'::jsonb, '["friendly","reflective","gentle"]'::jsonb, FALSE, NULL, 'Write down three things you are grateful for.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('grat-02', 'Even on heavy days, something held you â€” breath, shelter, one kind person. Name it.', 'Hard day thanks.', 'gratitude', '["low","struggling","okay"]'::jsonb, '["life-changes","failure","purpose"]'::jsonb, '["gentle","reflective"]'::jsonb, FALSE, NULL, 'Write down three things you are grateful for.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('grat-03', 'Unexpressed thanks fades. Tell one person specifically what they did and why it mattered.', 'Thank someone.', 'gratitude', '["good","great","okay"]'::jsonb, '["relationships","family","career"]'::jsonb, '["practical","friendly"]'::jsonb, FALSE, NULL, 'Thank one person specifically today.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('grat-04', 'Joy hides in normal moments â€” light, laughter, warm food. Photograph one and keep it.', 'Ordinary joy.', 'gratitude', '["good","okay","great"]'::jsonb, '["growth","family","purpose"]'::jsonb, '["friendly","reflective"]'::jsonb, FALSE, NULL, 'Photograph one ordinary good thing.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('grat-05', 'Someone makes your work easier daily. Naming their help builds a culture of gratitude.', 'Work thanks.', 'gratitude', '["good","okay"]'::jsonb, '["career","business","relationships"]'::jsonb, '["practical","friendly"]'::jsonb, FALSE, NULL, 'Thank one person specifically today.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('grat-06', 'End today by counting gains, not gaps. What worked, however small, deserves notice.', 'Evening review.', 'gratitude', '["good","okay","low"]'::jsonb, '["growth","purpose"]'::jsonb, '["reflective","gentle"]'::jsonb, FALSE, NULL, 'Write down three things you are grateful for.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('disc-01', 'Discipline is not intensity, it is consistency. Shrink the habit until you cannot say no.', 'Tiny habit.', 'discipline', '["okay","good","low"]'::jsonb, '["growth","growth","purpose"]'::jsonb, '["practical","direct","motivational"]'::jsonb, FALSE, NULL, 'Do the smallest version of your habit today (2 minutes counts).') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('disc-02', 'Mornings are won the night before. Prepare one thing tonight your future self will thank.', 'Night setup.', 'discipline', '["good","okay","great"]'::jsonb, '["growth","school","career"]'::jsonb, '["practical","friendly"]'::jsonb, FALSE, NULL, 'Lay out what you need for tomorrow tonight.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('disc-03', 'What gets marked gets maintained. Put one honest check on your habit tracker today.', 'Track it.', 'discipline', '["okay","good"]'::jsonb, '["growth","growth"]'::jsonb, '["direct","practical"]'::jsonb, FALSE, NULL, 'Track one habit with a simple check mark.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('disc-04', 'Missing once is an accident; missing twice is a pattern. Restart today without shame.', 'Missed yesterday?', 'discipline', '["low","okay","struggling"]'::jsonb, '["growth","failure","confidence"]'::jsonb, '["gentle","direct","motivational"]'::jsonb, FALSE, NULL, 'Do the smallest version of your habit today (2 minutes counts).') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('disc-05', 'Distraction is the enemy of depth. Give one task 25 undivided minutes and watch it move.', 'Focus block.', 'discipline', '["okay","good"]'::jsonb, '["school","business","career"]'::jsonb, '["bold","practical"]'::jsonb, FALSE, NULL, 'Track one habit with a simple check mark.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('disc-06', 'Slow and steady still finishes. Protect the streak by keeping today''s step tiny but done.', 'Steady wins.', 'discipline', '["good","okay","low"]'::jsonb, '["growth","purpose"]'::jsonb, '["reflective","friendly"]'::jsonb, FALSE, NULL, 'Lay out what you need for tomorrow tonight.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('lead-01', 'Great leaders notice effort before results. Praise one specific action you saw today.', 'Lead well.', 'leadership', '["good","okay","great"]'::jsonb, '["career","business","relationships"]'::jsonb, '["practical","friendly","motivational"]'::jsonb, FALSE, NULL, 'Encourage one person on your team specifically.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('lead-02', 'Unclear leadership is unkind. Make the delayed decision and communicate it with respect.', 'Decide kindly.', 'leadership', '["okay","good"]'::jsonb, '["career","business","family"]'::jsonb, '["direct","practical"]'::jsonb, FALSE, NULL, 'Decide one thing you have been delaying and communicate it.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('lead-03', 'Your job is to make their work easier. Ask what obstacle you can clear this week.', 'Serve team.', 'leadership', '["good","okay"]'::jsonb, '["career","business"]'::jsonb, '["friendly","reflective"]'::jsonb, FALSE, NULL, 'Ask your people what obstacle you can remove.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('lead-04', 'Teams borrow calm from their leader. Breathe, prioritize one thing, and speak hope plainly.', 'Under pressure.', 'leadership', '["low","okay","struggling"]'::jsonb, '["career","business","life-changes"]'::jsonb, '["gentle","bold"]'::jsonb, FALSE, NULL, 'Encourage one person on your team specifically.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('lead-05', 'At home, leadership is example. Do first what you ask of others â€” calmly and consistently.', 'Family lead.', 'leadership', '["good","okay"]'::jsonb, '["family","career"]'::jsonb, '["practical","gentle"]'::jsonb, FALSE, NULL, 'Ask your people what obstacle you can remove.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('lead-06', 'People endure hard todays when they see a meaningful tomorrow. Describe the why again today.', 'Vision cast.', 'leadership', '["good","great","okay"]'::jsonb, '["career","purpose","business"]'::jsonb, '["bold","motivational"]'::jsonb, FALSE, NULL, 'Decide one thing you have been delaying and communicate it.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('fam-01', 'Family bonds grow in listening, not lecturing. Call and let them finish their sentences today.', 'Call home.', 'family', '["good","okay","low"]'::jsonb, '["family","relationships"]'::jsonb, '["friendly","gentle","practical"]'::jsonb, FALSE, NULL, 'Call one family member just to listen.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('fam-02', 'One undistracted meal builds more trust than a week of hurried hellos. Put phones away.', 'Dinner table.', 'family', '["good","okay","great"]'::jsonb, '["family","relationships"]'::jsonb, '["practical","friendly"]'::jsonb, FALSE, NULL, 'Share one meal without phones today.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('fam-03', 'Charity starts at home. Speak one specific appreciation to someone under your roof.', 'Say thanks.', 'family', '["good","okay","low"]'::jsonb, '["family","growth"]'::jsonb, '["gentle","friendly"]'::jsonb, FALSE, NULL, 'Say one specific appreciation at home.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('fam-04', 'Volume never won understanding. Lower your voice, state needs clearly, and listen back.', 'Tense home?', 'family', '["low","struggling","okay"]'::jsonb, '["family","relationships"]'::jsonb, '["gentle","direct"]'::jsonb, FALSE, NULL, 'Call one family member just to listen.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('fam-05', 'Distance does not have to mean disconnection. One intentional call shrinks a thousand miles.', 'Far from home.', 'family', '["low","struggling","good"]'::jsonb, '["family","life-changes"]'::jsonb, '["friendly","reflective"]'::jsonb, FALSE, NULL, 'Call one family member just to listen.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('fam-06', 'Children remember tone more than words. Correct calmly today and connection will follow.', 'Parent heart.', 'family', '["okay","good","low"]'::jsonb, '["family","career"]'::jsonb, '["gentle","practical"]'::jsonb, FALSE, NULL, 'Say one specific appreciation at home.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('gro-01', 'You do not need to transform overnight. Fifteen focused minutes compounds into mastery.', 'Grow daily.', 'growth', '["good","okay","great"]'::jsonb, '["growth","school","career"]'::jsonb, '["practical","motivational","friendly"]'::jsonb, FALSE, NULL, 'Spend 15 minutes learning one small skill.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('gro-02', 'Growth is easier to see backward. Write what changed in you this month â€” you will be surprised.', 'Journal prompt.', 'growth', '["okay","good","low"]'::jsonb, '["growth","purpose"]'::jsonb, '["reflective","gentle"]'::jsonb, FALSE, NULL, 'Journal for five minutes: what grew in me this month?') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('gro-03', 'Trade ten minutes of scrolling for ten minutes of practice. Your future self keeps the difference.', 'Less scroll.', 'growth', '["okay","good","low"]'::jsonb, '["growth","growth"]'::jsonb, '["direct","practical","bold"]'::jsonb, FALSE, NULL, 'Replace 10 minutes of scrolling with practice.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('gro-04', 'Growth loves honest mirrors. Ask one trusted person what one thing you could improve.', 'Feedback gift.', 'growth', '["good","okay"]'::jsonb, '["growth","career","career"]'::jsonb, '["direct","friendly"]'::jsonb, FALSE, NULL, 'Spend 15 minutes learning one small skill.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('gro-05', 'Progress pauses before it jumps. Stay consistent through the flat part â€” the lift is coming.', 'Plateau season.', 'growth', '["low","okay","struggling"]'::jsonb, '["growth","failure"]'::jsonb, '["gentle","motivational"]'::jsonb, FALSE, NULL, 'Journal for five minutes: what grew in me this month?') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('gro-06', 'Read one page, practice one rep, write one line. Small daily inputs create large yearly shifts.', 'Morning learner.', 'growth', '["great","good","okay"]'::jsonb, '["growth","school"]'::jsonb, '["practical","friendly"]'::jsonb, FALSE, NULL, 'Replace 10 minutes of scrolling with practice.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('faith-01', 'God has not forgotten you in this waiting room. His timing is wiser than our hurry.', 'Peace for today.', 'faith', '["low","struggling","okay"]'::jsonb, '["purpose","life-changes","failure"]'::jsonb, '["spiritual","gentle","reflective"]'::jsonb, TRUE, 'Isaiah 40:31 â€” Those who hope in the Lord will renew their strength.', 'Read one short passage and sit in silence for two minutes.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('faith-02', 'Bring God your real feelings, not polished words. He can handle your honest heart today.', 'Morning prayer.', 'faith', '["low","okay","struggling"]'::jsonb, '["purpose","family","growth"]'::jsonb, '["spiritual","gentle"]'::jsonb, TRUE, 'Philippians 4:6 â€” Do not be anxious; present your requests to God.', 'Pray honestly for two minutes about today.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('faith-03', 'When you feel weak, grace is strongest. Lean on His strength, not just your own effort.', 'Strength verse.', 'faith', '["struggling","low"]'::jsonb, '["life-changes","failure"]'::jsonb, '["spiritual","bold"]'::jsonb, TRUE, '2 Corinthians 12:9 â€” My grace is sufficient for you.', 'Write one promise you are holding onto.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('faith-04', 'Every good gift has a Giver. Pause and thank God for three specific mercies today.', 'Gratitude prayer.', 'faith', '["good","great","okay"]'::jsonb, '["purpose","growth"]'::jsonb, '["spiritual","reflective"]'::jsonb, TRUE, 'James 1:17 â€” Every good and perfect gift is from above.', 'Write one promise you are holding onto.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('faith-05', 'Fear is not your shepherd. Walk into today knowing God goes ahead of you.', 'Courage in Christ.', 'faith', '["low","okay","struggling"]'::jsonb, '["purpose","career","confidence"]'::jsonb, '["spiritual","bold","motivational"]'::jsonb, TRUE, 'Joshua 1:9 â€” Be strong and courageous, for the Lord is with you.', 'Pray honestly for two minutes about today.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('faith-06', 'You do not have to strive without stopping. God built rest into rhythm for your good.', 'Rest in Him.', 'faith', '["low","struggling","okay"]'::jsonb, '["growth","life-changes"]'::jsonb, '["spiritual","gentle"]'::jsonb, TRUE, 'Matthew 11:28 â€” Come to me, all who are weary, and I will give you rest.', 'Read one short passage and sit in silence for two minutes.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('faith-07', 'Money worries test faith, not worth. Work wisely today and trust God with what you cannot control.', 'Provision trust.', 'faith', '["low","struggling","okay"]'::jsonb, '["finances","business"]'::jsonb, '["spiritual","practical"]'::jsonb, TRUE, 'Philippians 4:19 â€” God will meet all your needs.', 'Pray honestly for two minutes about today.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('faith-08', 'Speak blessing over your household today. Prayer covers what your presence cannot.', 'Family blessing.', 'faith', '["good","okay","low"]'::jsonb, '["family","relationships"]'::jsonb, '["spiritual","friendly"]'::jsonb, TRUE, 'Numbers 6:24 â€” The Lord bless you and keep you.', 'Pray honestly for two minutes about today.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('faith-09', 'His mercies are new every morning. Yesterday does not disqualify you from grace today.', 'New mercies.', 'faith', '["struggling","low","okay"]'::jsonb, '["failure","life-changes"]'::jsonb, '["spiritual","gentle","reflective"]'::jsonb, TRUE, 'Lamentations 3:22-23 â€” Great is His faithfulness; mercies new every morning.', 'Read one short passage and sit in silence for two minutes.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('faith-10', 'God shaped you with intention. Your gifts are clues to the assignment He trusts you with.', 'Purpose promise.', 'faith', '["okay","good","low"]'::jsonb, '["purpose","career"]'::jsonb, '["spiritual","reflective","motivational"]'::jsonb, TRUE, 'Jeremiah 29:11 â€” Plans to prosper you and give you hope.', 'Write one promise you are holding onto.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('faith-11', 'Do not throw away your confidence. The harvest comes to those who do not quit in faith.', 'Persevere.', 'faith', '["low","struggling","okay"]'::jsonb, '["business","failure","purpose"]'::jsonb, '["spiritual","bold"]'::jsonb, TRUE, 'Galatians 6:9 â€” Let us not grow weary in doing good.', 'Write one promise you are holding onto.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
INSERT INTO uplifts (id, body, greeting, category, moods, situations, styles, faith, scripture, action_text) VALUES ('faith-12', 'Anxiety argues loudly, but peace is stronger. Hand today''s worries to God one by one.', 'Peace prayer.', 'faith', '["struggling","low"]'::jsonb, '["purpose","life-changes"]'::jsonb, '["spiritual","gentle"]'::jsonb, TRUE, 'John 14:27 â€” Peace I leave with you; do not let your hearts be troubled.', 'Pray honestly for two minutes about today.') ON CONFLICT (id) DO UPDATE SET body=EXCLUDED.body, greeting=EXCLUDED.greeting, category=EXCLUDED.category, moods=EXCLUDED.moods, situations=EXCLUDED.situations, styles=EXCLUDED.styles, faith=EXCLUDED.faith, scripture=EXCLUDED.scripture, action_text=EXCLUDED.action_text;
